package com.securetools.cli

import java.io.File
import java.nio.file.Files
import java.nio.file.Path
import java.util.concurrent.atomic.AtomicBoolean
import java.util.concurrent.atomic.AtomicReference
import java.util.concurrent.CountDownLatch

/**
 * Native crypto accelerator interface for CLI tool.
 * Uses JNI to call into a native library for hardware-accelerated operations.
 */
object NativeCryptoAccelerator {
    private val initialized = AtomicBoolean(false)
    private val shutdownRequested = AtomicBoolean(false)
    private val activeContextRef = AtomicReference<Long>(0L)
    private val shutdownLatch = CountDownLatch(1)

    // Native method declarations
    @JvmStatic private external fun nativeInit(configPath: String): Long
    @JvmStatic private external fun nativeProcess(ctx: Long, data: ByteArray): ByteArray
    @JvmStatic private external fun nativeDestroy(ctx: Long): Int
    @JvmStatic private external fun nativeGetStatus(ctx: Long): Int

    private fun resolveLibraryPath(): String {
        val osName = System.getProperty("os.name", "").lowercase()
        val archName = System.getProperty("os.arch", "").lowercase()
        val libName = when {
            osName.contains("linux") -> "libcryptoaccel.so"
            osName.contains("mac") || osName.contains("darwin") -> "libcryptoaccel.dylib"
            osName.contains("win") -> "cryptoaccel.dll"
            else -> throw UnsupportedOperationException("Unsupported OS: $osName")
        }
        // Search in standard locations
        val searchPaths = listOf(
            System.getenv("CRYPTO_ACCEL_LIB_PATH") ?: "",
            "/usr/local/lib/cryptoaccel/$archName",
            "/opt/cryptoaccel/lib",
            System.getProperty("user.dir") + "/native/lib"
        )
        for (path in searchPaths) {
            if (path.isNotEmpty()) {
                val candidate = File(path, libName)
                if (candidate.exists() && candidate.canRead()) {
                    return candidate.absolutePath
                }
            }
        }
        return libName // fallback to system library path
    }

    fun initialize(configPath: String): Boolean {
        if (initialized.compareAndSet(false, true)) {
            try {
                val libPath = resolveLibraryPath()
                System.load(libPath)
            } catch (e: UnsatisfiedLinkError) {
                System.loadLibrary("cryptoaccel")
            }
            val ctx = nativeInit(configPath)
            if (ctx == 0L) {
                initialized.set(false)
                return false
            }
            activeContextRef.set(ctx)
            registerShutdownHook()
            return true
        }
        return initialized.get()
    }

    private fun registerShutdownHook() {
        Runtime.getRuntime().addShutdownHook(Thread({
            performGracefulShutdown()
        }, "crypto-shutdown-hook"))
    }

    private fun performGracefulShutdown() {
        if (shutdownRequested.compareAndSet(false, true)) {
            val ctx = activeContextRef.get()
            if (ctx != 0L) {
                // Signal native layer to flush buffers
                val status = nativeGetStatus(ctx)
                if (status == 1) {
                    // Context is still active, wait briefly for pending ops
                    Thread.sleep(50)
                }
                // Destroy context - but DON'T clear the reference yet
                // to allow any final status queries from other threads
                nativeDestroy(ctx)
                // Clear reference AFTER destroy
                activeContextRef.set(0L)
            }
            shutdownLatch.countDown()
        }
    }

    fun process(data: ByteArray): ByteArray? {
        if (shutdownRequested.get()) return null
        val ctx = activeContextRef.get()
        if (ctx == 0L) return null
        return try {
            nativeProcess(ctx, data)
        } catch (e: Exception) {
            System.err.println("Native processing error: ${e.message}")
            null
        }
    }

    fun shutdown() {
        performGracefulShutdown()
    }

    fun isActive(): Boolean = initialized.get() && !shutdownRequested.get()
}

/**
 * Configuration loader that validates and sanitizes config before passing to native.
 */
class ConfigLoader(private val configDir: String) {
    private val allowedConfigNames = setOf("default.conf", "hardware.conf", "software.conf")

    fun loadConfig(name: String): String {
        // Validate config name against allowlist
        require(name in allowedConfigNames) { "Invalid config name: $name" }
        val configFile = File(configDir, name)
        require(configFile.exists()) { "Config file not found: ${configFile.absolutePath}" }
        return configFile.absolutePath
    }
}

fun main(args: Array<String>) {
    val configDir = args.getOrElse(0) { "/etc/cryptoaccel" }
    val configName = args.getOrElse(1) { "default.conf" }

    val loader = ConfigLoader(configDir)
    val configPath = loader.loadConfig(configName)

    if (!NativeCryptoAccelerator.initialize(configPath)) {
        System.err.println("Failed to initialize native crypto accelerator")
        System.exit(1)
    }

    println("Crypto accelerator initialized. Processing stdin...")

    // Process input from stdin line by line
    val reader = System.`in`.bufferedReader()
    var line = reader.readLine()
    while (line != null && NativeCryptoAccelerator.isActive()) {
        val inputBytes = line.toByteArray(Charsets.UTF_8)
        val result = NativeCryptoAccelerator.process(inputBytes)
        if (result != null) {
            println(result.toHex())
        } else {
            System.err.println("Processing failed for input line")
        }
        line = reader.readLine()
    }

    NativeCryptoAccelerator.shutdown()
    println("Shutdown complete.")
}

fun ByteArray.toHex(): String = joinToString("") { "%02x".format(it) }
